@OptIn(ExperimentalFoundationApi::class)
@Composable
private fun ClickableCover(
    bitmap: Bitmap?,
    size: Dp,
    style: CoverStyle,
    isPlaying: Boolean,
    onClick: () -> Unit,
    onStyleSelect: (CoverStyle) -> Unit,
) {
    val description = stringResource(R.string.switch_to_lyrics)
    var styleMenuOpen by remember { mutableStateOf(false) }
    Box {
        val coverModifier = Modifier
            .combinedClickable(
                role = Role.Button,
                onClick = onClick,
                onLongClick = { styleMenuOpen = true },
            )
            .semantics { contentDescription = description }
        when (style) {
            CoverStyle.SQUARE -> CoverArt(
                bitmap = bitmap,
                modifier = Modifier
                    .size(size)
                    .then(coverModifier),
            )
            CoverStyle.CIRCLE -> Box(
                modifier = Modifier
                    .size(size)
                    .clip(CircleShape)
                    .background(MaterialTheme.colorScheme.surfaceVariant)
                    .then(coverModifier),
                contentAlignment = Alignment.Center,
            ) {
                if (bitmap != null) {
                    Image(
                        bitmap = bitmap.asImageBitmap(),
                        contentDescription = null,
                        modifier = Modifier.fillMaxSize(),
                        contentScale = ContentScale.Crop,
                    )
                }
            }
            CoverStyle.VINYL -> VinylCover(
                bitmap = bitmap,
                size = size,
                isPlaying = isPlaying,
                modifier = coverModifier,
            )
        }
        // 长按封面切换样式：方形 / 圆形 / 唱片。
        DropdownMenu(
            expanded = styleMenuOpen,
            onDismissRequest = { styleMenuOpen = false },
        ) {
            CoverStyle.entries.forEach { option ->
                DropdownMenuItem(
                    text = { Text(text = stringResource(option.coverStyleLabel)) },
                    leadingIcon = {
                        Icon(option.coverStyleIcon, contentDescription = null)
                    },
                    trailingIcon = {
                        if (option == style) {
                            Icon(Icons.Rounded.Check, contentDescription = null)
                        }
                    },
                    onClick = {
                        styleMenuOpen = false
                        onStyleSelect(option)
                    },
                )
            }
        }
    }
}

