 * 不能用 infiniteTransition，那种暂停/恢复会跳回起始角。
 */
@Composable
private fun rememberDiscRotation(isPlaying: Boolean): State<Float> {
    val rotation = remember { Animatable(0f) }
    LaunchedEffect(isPlaying) {
        if (!isPlaying) return@LaunchedEffect
        var lastFrameNanos = 0L
        while (true) {
            val frameNanos = withFrameNanos { it }
            if (lastFrameNanos != 0L) {
                val deltaDegrees = (frameNanos - lastFrameNanos) / 1_000_000f /
                    VINYL_ROTATION_PERIOD_MS * 360f
                rotation.snapTo((rotation.value + deltaDegrees) % 360f)
            }
            lastFrameNanos = frameNanos
        }
    }
    return rotation
}

