/** 底部弹窗升起 / 回弹 / 下滑关闭共用的弹簧（观感约 400ms、轻微过冲）。 */
private val SheetSpring = spring<Float>(dampingRatio = 0.85f, stiffness = 800f)
/** 展开时背后页面变圆角的最大值与压暗强度。 */
private const val BACKDROP_CORNER_DP = 28f
private const val BACKDROP_SCRIM_ALPHA = 0.34f
/** 往上拖的跟手阻力：手指移 1px 弹窗只动 0.32px。 */
private const val SHEET_DRAG_RESISTANCE = 0.32f
/** 往上拖能伸出的最大进度（阻力位移上限）。 */
private const val SHEET_MAX_OVER_DRAG = 1.15f
/** 下滑甩出速度阈值（dp/s）：超过即使位移不到 1/3 也判关闭。 */
private const val SHEET_FLING_CLOSE_DP = 350f

/** 弹窗内容里主动请求关闭（弹窗内“关闭 / 选择歌曲”等按钮用），带完整下滑动画。 */
val LocalSheetClose = staticCompositionLocalOf<() -> Unit> { {} }

/**
 * 统一的播放页底部弹窗：弹簧从底部升起，同时背后页面缩小到 0.92、变圆角、压暗。
 * 手指可上下拖动：往上拖有阻力；往下拖超过弹窗高度 1/3 或快速一甩即关闭，否则弹回原位；
 * 关闭的下滑与背后页面的恢复共用同一进度，全程同步。
 */
@Composable
private fun PlaybackBottomSheet(
    onDismiss: () -> Unit,
    blurredCover: Bitmap,
    playbackScheme: ColorScheme,
    backdrop: MutableFloatState,
    title: String? = null,
    scrollable: Boolean = false,
    content: @Composable ColumnScope.() -> Unit,
) {
    val scope = rememberCoroutineScope()
    val density = LocalDensity.current
    val scrollState = rememberScrollState()
    // 0 = 完全在屏下，1 = 就位；>1 是往上拖出的位移（带阻力）。
    // 背后页面的缩小/圆角/压暗与 scrim 都直接读它，任何时刻同步。
    val progress = remember { Animatable(0f) }
    var contentHeightPx by remember { mutableIntStateOf(0) }
    var dismissed by remember { mutableStateOf(false) }
    val velocityTracker = remember { VelocityTracker() }

    LaunchedEffect(Unit) {
        snapshotFlow { progress.value }
            .collect { backdrop.floatValue = it.coerceIn(0f, 1f) }
    }
    LaunchedEffect(Unit) {
        progress.animateTo(1f, SheetSpring)
    }

    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        // 滑动基准距离：用整屏高，保证初始完全在屏外。
        val slidePx = constraints.maxHeight.toFloat()
        val flingClosePx = with(density) { SHEET_FLING_CLOSE_DP.dp.toPx() }

        fun close(flingPxPerS: Float) {
            if (dismissed) return
            dismissed = true
            scope.launch {
                progress.animateTo(
                    0f,
                    SheetSpring,
                    initialVelocity = -flingPxPerS / slidePx,
                )
                onDismiss()
            }
        }
        fun settle(flingPxPerS: Float) {
            if (dismissed) return
            val offsetPx = (1f - progress.value) * slidePx
            if (offsetPx > contentHeightPx / 3f || flingPxPerS > flingClosePx) {
                close(flingPxPerS)
            } else {
                scope.launch {
                    progress.animateTo(
                        1f,
                        SheetSpring,
                        initialVelocity = flingPxPerS / slidePx,
                    )
                }
            }
        }
        fun dragBy(dyPx: Float) {
            if (dismissed) return
            progress.snapTo((progress.value - dyPx / slidePx).coerceIn(0f, SHEET_MAX_OVER_DRAG))
        }

        // 可滚动内容：滚到顶后继续向下拖，把位移转给弹窗整体（与手势拖动同一套关闭判定）。
        val nestedConnection = object : NestedScrollConnection {
            override fun onPreScroll(available: Offset, source: NestedScrollSource): Offset {
                if (available.y > 0f && !dismissed && progress.value <= 1.0001f) {
                    val before = progress.value
                    dragBy(available.y)
                    return Offset(0f, (before - progress.value) * slidePx)
                }
                return Offset.Zero
            }

            override suspend fun onPreFling(available: Velocity): Velocity {
                if (available.y > 0f && !dismissed) {
                    settle(available.y)
                    return available
                }
                return Velocity.Zero
            }
        }

        val dragModifier = Modifier.pointerInput(Unit) {
            detectVerticalDragGestures(
                onDragStart = { velocityTracker.resetTracking() },
                onDragEnd = {
                    settle(velocityTracker.calculateVelocity().y)
                },
                onDragCancel = { settle(0f) },
                onVerticalDrag = { change, dragAmount ->
                    change.consume()
                    velocityTracker.addPosition(change.uptimeMillis, change.position)
                    // 往上拖给阻力，往下拖 1:1 跟手。
                    val factor = if (dragAmount < 0f) SHEET_DRAG_RESISTANCE else 1f
                    dragBy(dragAmount * factor)
                },
            )
        }

        // 背板压暗：点击空白处关闭，透明度跟进度走（含升起 / 拖动 / 下滑全程）。
        Box(
            modifier = Modifier
                .fillMaxSize()
                .graphicsLayer { alpha = progress.value.coerceIn(0f, 1f) }
                .background(Color.Black.copy(alpha = 0.42f))
                .pointerInput(Unit) { detectTapGestures { close(0f) } },
        )
        Box(
            modifier = Modifier
                .align(Alignment.BottomCenter)
                .fillMaxWidth()
                .navigationBarsPadding()
                .graphicsLayer { translationY = (1f - progress.value) * slidePx }
                .onSizeChanged { contentHeightPx = it.height }
                .nestedScroll(nestedConnection)
                .then(dragModifier),
        ) {
            MaterialTheme(colorScheme = playbackScheme) {
                Box(
                    modifier = Modifier
                        .fillMaxWidth()
                        .clip(RoundedCornerShape(topStart = 26.dp, topEnd = 26.dp)),
                ) {
                    Box(modifier = Modifier.matchParentSize()) {
                        CoverBackdrop(bitmap = blurredCover)
                    }
                    Column(
                        modifier = Modifier
                            .fillMaxWidth()
                            .then(
                                if (scrollable) {
                                    Modifier.verticalScroll(scrollState)
                                } else {
                                    Modifier
                                },
                            )
                            .padding(horizontal = 20.dp)
                            .padding(bottom = 24.dp),
                    ) {
                        SheetDragHandle()
                        if (title != null) {
                            Text(
                                text = title,
                                style = MaterialTheme.typography.titleLarge,
                                color = Color.White,
                                modifier = Modifier.padding(bottom = 8.dp),
                            )
                        }
                        CompositionLocalProvider(
                            LocalSheetClose provides {
                                close(0f)
