val scope = rememberCoroutineScope()
val density = LocalDensity.current
val scrollState = rememberScrollState()
// 0 = 完全在屏下，1 = 就位；>1 是往上拖出的位移（带阻力）。
// 背后页面的缩小/圆角/压暗与 scrim 都直接读它，任何时刻同步。
val progress = remember { Animatable(0f) }
var contentHeightPx by remember { mutableIntStateOf(0) }
var dismissed by remember { mutableStateOf(false) }
val velocityTracker = remember { VelocityTracker() }

LaunchedEffect(Unit) {
    snapshotFlow { progress.value }
        .collect { backdrop.floatValue = it.coerceIn(0f, 1f) }
}
LaunchedEffect(Unit) {
    progress.animateTo(1f, SheetSpring)
}

BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
    // 滑动基准距离：用整屏高，保证初始完全在屏外。
    val slidePx = constraints.maxHeight.toFloat()
    val flingClosePx = with(density) { SHEET_FLING_CLOSE_DP.dp.toPx() }

    fun close(flingPxPerS: Float) {
        if (dismissed) return
        dismissed = true
        scope.launch {
            progress.animateTo(
                0f,
                SheetSpring,
                initialVelocity = -flingPxPerS / slidePx,
            )
            onDismiss()
        }
    }
    fun settle(flingPxPerS: Float) {
        if (dismissed) return
        val offsetPx = (1f - progress.value) * slidePx
        if (offsetPx > contentHeightPx / 3f || flingPxPerS > flingClosePx) {
            close(flingPxPerS)
        } else {
            scope.launch {
                progress.animateTo(
                    1f,
                    SheetSpring,
                    initialVelocity = flingPxPerS / slidePx,
                )
            }
        }
    }
    fun dragBy(dyPx: Float) {
        if (dismissed) return
        progress.snapTo((progress.value - dyPx / slidePx).coerceIn(0f, SHEET_MAX_OVER_DRAG))
    }

val scope = rememberCoroutineScope()
val density = LocalDensity.current
val scrollState = rememberScrollState()
// 0 = 完全在屏下，1 = 就位；>1 是往上拖出的位移（带阻力）。
// 背后页面的缩小/圆角/压暗与 scrim 都直接读它，任何时刻同步。
// 拖动要在手势回调里非挂起写值，所以进度本体是 FloatState，
// 弹簧动画用 Animatable 桥接、逐帧写回 FloatState。
val progress = remember { mutableFloatStateOf(0f) }
val progressAnim = remember { Animatable(0f) }
var contentHeightPx by remember { mutableIntStateOf(0) }
var dismissed by remember { mutableStateOf(false) }
val velocityTracker = remember { VelocityTracker() }

LaunchedEffect(Unit) {
    snapshotFlow { progress.value }
        .collect { backdrop.floatValue = it.coerceIn(0f, 1f) }
}
// 升起。
LaunchedEffect(Unit) {
    progressAnim.snapTo(0f)
    progressAnim.animateTo(1f, SheetSpring) { progress.floatValue = it.value }
}

BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
    // 滑动基准距离：用整屏高，保证初始完全在屏外。
    val slidePx = constraints.maxHeight.toFloat()
    val flingClosePx = with(density) { SHEET_FLING_CLOSE_DP.dp.toPx() }

    fun close(flingPxPerS: Float) {
        if (dismissed) return
        dismissed = true
        scope.launch {
            progressAnim.snapTo(progress.floatValue)
            progressAnim.animateTo(
                0f,
                SheetSpring,
                initialVelocity = -flingPxPerS / slidePx,
            ) { progress.floatValue = it.value }
            onDismiss()
        }
    }
    fun settle(flingPxPerS: Float) {
        if (dismissed) return
        val offsetPx = (1f - progress.floatValue) * slidePx
        if (offsetPx > contentHeightPx / 3f || flingPxPerS > flingClosePx) {
            close(flingPxPerS)
        } else {
            scope.launch {
                progressAnim.snapTo(progress.floatValue)
                progressAnim.animateTo(
                    1f,
                    SheetSpring,
                    initialVelocity = flingPxPerS / slidePx,
                ) { progress.floatValue = it.value }
            }
        }
    }
    fun dragBy(dyPx: Float) {
        if (dismissed) return
        progress.floatValue =
            (progress.floatValue - dyPx / slidePx).coerceIn(0f, SHEET_MAX_OVER_DRAG)
    }

